// T17: the submission's source list and AI-use summary, collected from docs/sources/ and
// docs/ai-use/, and the last check before submitting.
//
//   node pitch/tools/sources.mjs build                  writes pitch/references.md and pitch/ai-use.md
//   node pitch/tools/sources.mjs check [--site URL]     every file is covered (exit 1 if not)
//
// "check" compares the docs/ folders on disk with the two generated files, and with
// --site also opens the deployed site's About panel and looks for every file there (needs
// `npm ci` in web/). Run it on main after the last pull request has merged (T17, "Done when").

import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { basename, dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const repo = resolve(here, '../..');
const REPO_URL = 'https://github.com/glyft-nasa2026/Darksight';

const cells = (line) => line.trim().replace(/^\||\|$/g, '').split('|').map((c) => c.trim());
const isSep = (line) => /^\|[\s:|-]+\|$/.test(line.trim());

/**
 * Body rows of the tables in a markdown file whose header passes `keep`, as arrays of cells
 * (each with its table's `header`). Other tables in the file (results, choices) are skipped.
 */
export function tableRows(md, keep = () => true) {
  const lines = md.split(/\r?\n/);
  const rows = [];
  let header = null;
  for (let i = 0; i < lines.length; i++) {
    const l = lines[i].trim();
    // A table may carry on after a few lines of text (docs/ai-use/T19.md): rows keep the last
    // header until a new one appears.
    if (!l.startsWith('|')) continue;
    if (isSep(l)) continue;
    if (isSep(lines[i + 1] ?? '')) { header = cells(l); continue; }
    if (header && keep(header)) rows.push(Object.assign(cells(l), { header }));
  }
  return rows;
}

// Source tables start "What | Used for | Link | Licence" (or "Source | Use"); AI-use tables have
// a "Tool" column.
const KEEP = {
  sources: (h) => /^(what|source)$/i.test(h[0] ?? ''),
  'ai-use': (h) => h.some((c) => /^tool$/i.test(c)),
};

const urlsIn = (s) => [...s.matchAll(/https?:\/\/[^\s)<>|`,]+/g)].map((m) => m[0].replace(/[.;]+$/, ''));
const plain = (s) => s.replace(/\[([^\]]+)\]\([^)]*\)/g, '$1').replace(/`/g, '').trim();

function readDir(dir) {
  const abs = join(repo, 'docs', dir);
  return readdirSync(abs).filter((f) => f.endsWith('.md')).sort((a, b) => a.localeCompare(b, 'en', { numeric: true }))
    .map((f) => ({ id: basename(f, '.md'), path: `docs/${dir}/${f}`, rows: tableRows(readFileSync(join(abs, f), 'utf8'), KEEP[dir]) }));
}

const label = (id) => id.replace(/^issue-(\d+)$/, 'Issue #$1');

function buildReferences(files) {
  // One line per distinct source: keyed by its first web address, else by its name.
  const byKey = new Map();
  for (const f of files) {
    for (const r of f.rows) {
      const [what = '', , link = '', licence = ''] = r;
      const urls = urlsIn(r.join(' '));
      const key = urls[0] ?? plain(what).toLowerCase();
      if (!key) continue;
      const e = byKey.get(key) ?? { what: plain(what), urls: new Set(), licence: plain(licence), tasks: new Set(), local: plain(link) };
      urls.forEach((u) => e.urls.add(u));
      e.tasks.add(f.id);
      byKey.set(key, e);
    }
  }
  const all = [...byKey.values()];
  const web = all.filter((e) => e.urls.size).sort((a, b) => a.what.localeCompare(b.what));
  const local = all.filter((e) => !e.urls.size).sort((a, b) => a.what.localeCompare(b.what));
  const esc = (s) => s.replace(/\|/g, '\\|');
  const out = [
    '# Darksight: every source, collected from `docs/sources/`',
    '',
    'Generated by `node pitch/tools/sources.mjs build`; do not edit by hand. Each task\'s own file in',
    `[docs/sources/](${REPO_URL}/tree/main/docs/sources) has the detail. The deployed site\'s About`,
    'panel shows the same files.',
    '',
    `Files: ${files.length} (${files.filter((f) => f.rows.length).length} with entries). Distinct sources: ${all.length}.`,
    '',
    '## Data, papers, libraries and web pages',
    '',
    '| Source | Link | Licence or terms | Tasks |',
    '|---|---|---|---|',
    ...web.map((e) => `| ${esc(e.what)} | ${[...e.urls].map((u) => `<${u}>`).join(' ')} | ${esc(e.licence)} | ${[...e.tasks].map(label).join(', ')} |`),
    '',
    '## Project files, standard formulas and values without a web address',
    '',
    '| Source | Where | Tasks |',
    '|---|---|---|',
    ...local.map((e) => `| ${esc(e.what)} | ${esc(e.local)} | ${[...e.tasks].map(label).join(', ')} |`),
    '',
    '## Files with no entries yet',
    '',
    files.filter((f) => !f.rows.length).map((f) => `\`${f.path}\``).join(', ') || 'None.',
    '',
  ];
  return out.join('\n');
}

function buildAiUse(files) {
  const tools = new Map();
  const per = files.map((f) => {
    const ts = new Set();
    for (const r of f.rows) {
      const t = r[r.header.findIndex((c) => /^tool$/i.test(c))] ?? '';
      if (t) {
        ts.add(t);
        tools.set(t, (tools.get(t) ?? 0) + 1);
      }
    }
    return { ...f, tools: [...ts] };
  });
  const out = [
    '# Darksight: AI use, collected from `docs/ai-use/`',
    '',
    'Generated by `node pitch/tools/sources.mjs build`; do not edit by hand. Each task\'s own file in',
    `[docs/ai-use/](${REPO_URL}/tree/main/docs/ai-use) has every row: what the AI generated and`,
    'what a person checked. The deployed site\'s About panel shows the same rows.',
    '',
    `Files: ${files.length} (${files.filter((f) => f.rows.length).length} with entries). Rows: ${files.reduce((n, f) => n + f.rows.length, 0)}.`,
    '',
    '## Tools named, with the number of rows',
    '',
    '| Tool | Rows |',
    '|---|---|',
    ...[...tools.entries()].sort((a, b) => b[1] - a[1]).map(([t, n]) => `| ${t} | ${n} |`),
    '',
    '## Per file',
    '',
    '| File | Rows | Tools |',
    '|---|---|---|',
    ...per.map((f) => `| [${f.id}](${REPO_URL}/blob/main/${f.path}) | ${f.rows.length} | ${f.tools.join(', ') || (f.rows.length ? 'see file' : 'no entries yet')} |`),
    '',
  ];
  return out.join('\n');
}

async function siteCheck(site, sources, ai) {
  const require = createRequire(join(repo, 'web/package.json'));
  const { chromium } = require('@playwright/test');
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.goto(site, { waitUntil: 'domcontentloaded' });
  await page.getByRole('button', { name: 'Start exploring' }).click().catch(() => undefined);
  await page.waitForFunction(() => !document.body.classList.contains('intro-open'), null, { timeout: 120_000 });
  await page.locator('#about button.about-open').click();
  await page.waitForFunction(() => {
    const t = document.querySelector('#about dialog')?.textContent ?? '';
    return !/Loading sources…|Loading the AI-use notes…/.test(t);
  }, null, { timeout: 60_000 });
  // Each task is a <summary> like "T07 · 18" under the panel's "Data sources" or "How AI was used"
  // heading. textContent, not innerText: the headings are upper-cased by CSS.
  const found = await page.evaluate(() => {
    const d = document.querySelector('#about dialog');
    const parts = { sources: [], ai: [] };
    let part = null;
    for (const el of d.querySelectorAll('h3, summary')) {
      const t = el.textContent.trim();
      if (el.tagName === 'H3') part = t === 'Data sources' ? 'sources' : t === 'How AI was used' ? 'ai' : null;
      else if (part) parts[part].push(t.split(' · ')[0].trim());
    }
    return parts;
  });
  await browser.close();
  return {
    sources: sources.filter((f) => f.rows.length && !found.sources.includes(label(f.id))).map((f) => f.path),
    ai: ai.filter((f) => f.rows.length && !found.ai.includes(label(f.id))).map((f) => f.path),
  };
}

const [mode = 'check', ...rest] = process.argv.slice(2);
const sources = readDir('sources');
const ai = readDir('ai-use');

if (mode === 'build') {
  writeFileSync(join(repo, 'pitch/references.md'), buildReferences(sources));
  writeFileSync(join(repo, 'pitch/ai-use.md'), buildAiUse(ai));
  console.log(`pitch/references.md: ${sources.length} files; pitch/ai-use.md: ${ai.length} files`);
} else if (mode === 'check') {
  let failed = false;
  const refs = readFileSync(join(repo, 'pitch/references.md'), 'utf8');
  const aiMd = readFileSync(join(repo, 'pitch/ai-use.md'), 'utf8');
  if (refs !== buildReferences(sources) || aiMd !== buildAiUse(ai)) {
    console.log('FAIL pitch/references.md or pitch/ai-use.md is out of date: run "node pitch/tools/sources.mjs build"');
    failed = true;
  } else {
    console.log(`PASS submission lists: ${sources.length} docs/sources files and ${ai.length} docs/ai-use files, all collected`);
  }
  for (const f of [...sources, ...ai].filter((x) => !x.rows.length)) console.log(`note ${f.path}: no entries yet`);
  const si = rest.indexOf('--site');
  if (si >= 0) {
    const site = rest[si + 1] ?? 'https://darksight.space/';
    const miss = await siteCheck(site, sources, ai);
    if (miss.sources.length || miss.ai.length) {
      failed = true;
      console.log(`FAIL About panel on ${site} is missing:\n  ${[...miss.sources, ...miss.ai].join('\n  ')}`);
      console.log('  -> arrange one more T16 delivery (or a redeploy of main) and check again');
    } else {
      console.log(`PASS About panel on ${site} shows every file with entries`);
    }
  }
  process.exit(failed ? 1 : 0);
} else {
  console.error('Usage: node pitch/tools/sources.mjs build | check [--site URL]');
  process.exit(2);
}
